var frame=UnityEngine.GameObject.Find("V015 package - glass ecology garden").transform;
var rows=new System.Collections.Generic.List<object>();
foreach(var mf in frame.GetComponentsInChildren<UnityEngine.MeshFilter>()){
 if(!mf.sharedMesh||mf.name.Contains("LOD")||mf.name.Contains("foliage"))continue;
 var vertices=mf.sharedMesh.vertices.Select(v=>frame.InverseTransformPoint(mf.transform.TransformPoint(v))).ToArray();
 if(vertices.Length==0)continue;
 var min=new UnityEngine.Vector3(vertices.Min(v=>v.x),vertices.Min(v=>v.y),vertices.Min(v=>v.z));var max=new UnityEngine.Vector3(vertices.Max(v=>v.x),vertices.Max(v=>v.y),vertices.Max(v=>v.z));
 if(min.y<2.8f||max.y>8)continue;
 rows.Add(new{path=UnityEditor.AnimationUtility.CalculateTransformPath(mf.transform,frame),min=min.ToString("F2"),max=max.ToString("F2"),mesh=UnityEditor.AssetDatabase.GetAssetPath(mf.sharedMesh)});
}
return rows;
